import fs from 'node:fs/promises'
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE || 'playwright')
const dir='deliverables/commercial-relationships-2026-09-15'
const r=JSON.parse(await fs.readFile(`${dir}/relationship-register.json`))
const logo='data:image/png;base64,'+(await fs.readFile('public/brand/saturn-star-horizontal-full-color.png')).toString('base64')
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>')
function markdown(md){const lines=md.split('\n');let html='';for(let i=0;i<lines.length;i++){const l=lines[i].trim();if(!l)continue;if(l.startsWith('|')){let rows=[];while(i<lines.length&&lines[i].trim().startsWith('|')){const cells=lines[i].trim().slice(1,-1).split('|').map(x=>x.trim());if(!cells.every(x=>/^[-: ]+$/.test(x)))rows.push(cells);i++}i--;html+='<table>'+rows.map((row,j)=>'<tr>'+row.map(c=>`<${j?'td':'th'}>${inline(c)}</${j?'td':'th'}>`).join('')+'</tr>').join('')+'</table>';continue}const h=l.match(/^(#{1,3}) (.*)/);if(h){html+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;continue}if(/^[-*] /.test(l)){html+='<p class="bullet">• '+inline(l.slice(2))+'</p>';continue}html+='<p>'+inline(l)+'</p>'}return html}
const css=`@page{size:Letter;margin:.65in}*{box-sizing:border-box}body{font:11pt/1.55 Arial,sans-serif;color:#17212b;margin:0}header{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #c99700;padding-bottom:18px;margin-bottom:26px}header img{width:210px}header span{font-size:9px;color:#667085;text-align:right}h1{font-size:27pt;line-height:1.12;color:#071421;margin:20px 0}h2{font-size:16pt;color:#071421;border-bottom:2px solid #c99700;padding-bottom:7px;margin:27px 0 12px;break-after:avoid}h3{font-size:12pt;break-after:avoid}p{margin:0 0 12px;orphans:3;widows:3}.bullet{padding-left:12px}table{border-collapse:collapse;width:100%;font-size:8.5pt;margin:18px 0}th{background:#071421;color:white;text-align:left}td,th{padding:8px;border:1px solid #ddd;vertical-align:top}tr{break-inside:avoid}a{color:#8a6800}code{font-size:8pt;overflow-wrap:anywhere}footer{border-top:1px solid #c99700;padding-top:14px;margin-top:40px;font-size:9pt;color:#667085}.letter{break-after:page}.letter:last-child{break-after:auto}.label{color:#8a6800;font-size:9pt;letter-spacing:1px;text-transform:uppercase}.recipient{margin:26px 0 30px}.proof{background:#f7f4ed;padding:12px 14px;font-size:9pt;margin:20px 0 28px}.signature{margin-top:28px}strong{color:#071421}`
const header=label=>`<header><img src="${logo}" alt="Saturn Star Movers"><span>${esc(label)}<br>September 15, 2026</span></header>`
const wrap=(title,body)=>`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>${css}</style></head><body>${body}</body></html>`
const addresses={huli:'Confirm the recipient’s current business mailing address before posting.',stclair:'Kyle Revait • St. Clair College<br>2000 Talbot Road West<br>Windsor, ON N9A 6S4',steelcraft:'Confirm William’s preferred office. Historical finance address: 151 Arrow Road, Guelph, ON N1K 1S8; not verified as his mailing route.',cbsa:'Confirm Patrick’s preferred business mailing address before posting.'}
const letterHTML=wrap('Commercial Relationship Letter Proofs',r.drafts.map(m=>{const person=r.people.find(p=>p.id===m.contactId);const body=m.body.split('\n\nJohn Owolabi')[0];return `<section class="letter">${header('LETTER PROOF — NOT POSTED')}<div class="recipient"><strong>${esc(person.name)}</strong><br>${esc(r.accounts.find(a=>a.key===m.key).name)}</div><p class="label">${esc(m.subject)}</p>${body.split('\n\n').map(p=>'<p>'+esc(p).replaceAll('\n','<br>')+'</p>').join('')}<p class="signature"><strong>John Owolabi</strong><br>Partnerships | Saturn Star Movers<br>business@starmovers.ca<br>starmovers.ca</p><footer>Moving support across Southwestern Ontario<br>Scope, access and availability confirmed for each request.</footer><div class="proof"><strong>Internal mailing note:</strong> ${addresses[m.key]}<br>Email has already been sent. Review the reply and adapt this letter before arranging postage; do not send duplicate copy automatically.</div></section>`}).join(''))
const md=await fs.readFile('docs/commercial-partnership-playbook.md','utf8')
const bookHTML=wrap('Commercial Partnership Playbook',header('INTERNAL WORKING PLAYBOOK')+markdown(md))
await fs.writeFile(`${dir}/letter-proofs.html`,letterHTML);await fs.writeFile(`${dir}/playbook.html`,bookHTML)
const browser=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_EXECUTABLE});try{for(const [name,html] of [['letter-proofs',letterHTML],['playbook',bookHTML]]){const page=await browser.newPage();await page.setContent(html,{waitUntil:'load'});await page.emulateMedia({media:'print'});await page.pdf({path:`${dir}/${name}.pdf`,format:'Letter',printBackground:true,preferCSSPageSize:true});if(name==='letter-proofs'){await page.setViewportSize({width:816,height:1056});await page.screenshot({path:`${dir}/letter-preview.png`,fullPage:false})}console.log(name,(await fs.stat(`${dir}/${name}.pdf`)).size);await page.close()}}finally{await browser.close()}
